import React from 'react';
import type { FC } from 'react';
import { match } from 'variant';
import type { DeploymentTopologyEnvironmentType } from '@wix/cli-astro-definitions';
import { ActionStatus } from './ActionStatus.js';
import { useCreatePreview } from './hooks/useCreatePreview.js';
import type { PreviewResult } from './hooks/useCreatePreview.js';
import { SiteTopologyAndLinks } from './SiteTopologyAndLinks.js';
import { AppTopologyAndLinks } from './AppTopologyAndLinks.js';

export type { PreviewResult } from './hooks/useCreatePreview.js';

export const Preview: FC<{
  environment: DeploymentTopologyEnvironmentType;
  baseUrl?: string;
  label?: string;
  previewId?: string;
  onPreviewCreated?: (result: PreviewResult) => void;
}> = ({ environment, baseUrl, label, previewId, onPreviewCreated }) => {
  const { uploadStatus, createPreviewStatus, status } = useCreatePreview({
    baseUrl,
    label,
    previewId,
  });

  return (
    <>
      <ActionStatus
        status={uploadStatus}
        loadingText={'Uploading your application files...'}
        successText={'Uploaded successfully!'}
      />
      <ActionStatus
        status={createPreviewStatus}
        loadingText={'Creating a preview...'}
        successText={'Preview created successfully!'}
      />
      {match(status, {
        Error: () => null,
        Loading: () => null,
        Success: ({ result }) =>
          match(result.deployment, {
            Site: ({ deploymentUrl }) => (
              <SiteTopologyAndLinks
                environment={environment}
                previewUrl={deploymentUrl}
                previewId={result.previewId}
                onTopologyUpdated={() =>
                  onPreviewCreated?.({
                    deployment: result.deployment,
                    previewId: result.previewId,
                    appManifest: result.appManifest,
                  })
                }
              />
            ),
            App: () => (
              <AppTopologyAndLinks
                environment={environment}
                previewId={result.previewId}
                onTopologyUpdated={() =>
                  onPreviewCreated?.({
                    deployment: result.deployment,
                    previewId: result.previewId,
                    appManifest: result.appManifest,
                  })
                }
              />
            ),
          }),
      })}
    </>
  );
};
