import React from 'react';
import type { FC } from 'react';
import { match } from 'variant';
import { useAsync } from '@wix/cli-ui-kit';
import type { DeploymentTopologyEnvironmentType } from '@wix/cli-astro-definitions';
import { ActionStatus } from './ActionStatus.js';
import { useUpdateDeploymentTopologyForApp } from '../../hooks/useUpdateDeploymentTopology.js';
import { PlatformLinksSection } from '../PlatformLink/PlatformLinksSection.js';
import {
  getPlatformLinkCommand,
  useAppLinks,
} from '../../platform-links/resolve.js';

export const AppTopologyAndLinks: FC<{
  environment: DeploymentTopologyEnvironmentType;
  previewId: string;
  onTopologyUpdated: () => void;
}> = ({ environment, previewId, onTopologyUpdated }) => {
  const updateDeploymentTopology = useUpdateDeploymentTopologyForApp();
  const links = useAppLinks({
    cmd: getPlatformLinkCommand(environment),
    overrideId: previewId,
  });

  const { status } = useAsync(async () => {
    await updateDeploymentTopology({
      versionOverrideId: previewId,
      environment,
    });

    onTopologyUpdated();
  }, []);

  return (
    <>
      <ActionStatus
        status={status}
        loadingText={'Updating deployment topology manifest...'}
        successText={'Deployment topology manifest updated successfully!'}
      />
      {match(status, {
        Error: () => null,
        Loading: () => null,
        Success: () => <PlatformLinksSection links={links} />,
      })}
    </>
  );
};
