import React from 'react';
import type { FC } from 'react';
import { match } from 'variant';
import { useAsync } from '@wix/cli-ui-kit';
import type { DeploymentTopologyEnvironmentType } from '@wix/cli-astro-definitions';
import { OnboardingState, useVeloClient } from '@wix/velo-client';
import { ActionStatus } from './ActionStatus.js';
import { PlatformLinksSection } from '../PlatformLink/PlatformLinksSection.js';
import {
  getPlatformLinkCommand,
  useSiteLinks,
} from '../../platform-links/resolve.js';
import { useUpdateDeploymentTopologyForSite } from '../../hooks/useUpdateDeploymentTopology.js';
import { useSiteConfig } from '../../model.js';

export const SiteTopologyAndLinks: FC<{
  environment: DeploymentTopologyEnvironmentType;
  previewId: string;
  previewUrl: string;
  onTopologyUpdated: () => void;
}> = ({ environment, previewId, previewUrl, onTopologyUpdated }) => {
  const { appId, siteId } = useSiteConfig();
  const updateDeploymentTopology = useUpdateDeploymentTopologyForSite(siteId);
  const veloClient = useVeloClient();
  const links = useSiteLinks({
    cmd: getPlatformLinkCommand(environment),
    siteId,
    overrideId: previewId,
    siteUrl: previewUrl,
  });

  const { status } = useAsync(async () => {
    const [, gitHubOnboarding] = await Promise.all([
      updateDeploymentTopology({
        siteUrl: previewUrl,
        versionOverrideId: previewId,
        environment,
      }),
      veloClient.getGitHubOnboardingStatus(appId),
    ]);

    onTopologyUpdated();

    return { gitHubOnboarding };
  }, []);

  return (
    <>
      <ActionStatus
        status={status}
        loadingText={'Updating deployment topology manifest...'}
        successText={'Deployment topology manifest updated successfully!'}
      />
      {match(status, {
        Error: () => null,
        Loading: () => null,
        Success: ({ result: { gitHubOnboarding } }) => {
          const isGitHubEnabled =
            gitHubOnboarding?.status === OnboardingState.GITHUB_ENABLED;
          const visibleLinks = isGitHubEnabled
            ? links
            : links.filter((link) => link.platform !== 'editor');

          return <PlatformLinksSection links={visibleLinks} />;
        },
      })}
    </>
  );
};
