import { useAsync, useAsyncCallback } from '@wix/cli-ui-kit';
import { CliError, CliErrorCode } from '@wix/cli-error';
import type { LooseAppManifest } from '@wix/cli-app-manifest';
import { fields, variant } from 'variant';
import type { VariantOf } from 'variant';
import {
  toComponentExperiments,
  useDevCenterOverridesClient,
} from '@wix/dev-center-overrides-client';
import { isInsideGitRepo, getGitLatestCommitHash } from '@wix/package-manager';
import { useProjectModel } from '../../../model.js';
import { assertBuildOutputExists } from '../../../files/assert-build-output-exists.js';
import { processAppManifest } from '../../../app-manifest/file.js';
import { useLoadBuildFiles } from './useLoadBuildFiles.js';
import { useUpdateManifest } from './useUpdateManifest.js';
import { useDeployFiles } from './useDeployFiles.js';

const DeploymentTarget = variant({
  Site: fields<{ deploymentUrl: string; deploymentId?: string }>(),
  App: fields<{ deploymentUrl?: string; deploymentId?: string }>(),
});

type DeploymentTarget = VariantOf<typeof DeploymentTarget>;

export interface PreviewResult {
  deployment: DeploymentTarget;
  previewId: string;
  appManifest: LooseAppManifest;
}

export function useCreatePreview({
  baseUrl,
  label,
  previewId: existingPreviewId,
  onPreviewCreated,
}: {
  baseUrl?: string;
  label?: string;
  previewId?: string;
  onPreviewCreated?: (result: PreviewResult) => void;
}) {
  const { model } = useProjectModel();

  const devCenterOverrides = useDevCenterOverridesClient();
  const loadBuildFiles = useLoadBuildFiles();
  const deployFiles = useDeployFiles();
  const { updateManifestWithBackendWorker } = useUpdateManifest();

  const uploadApplicationAction = useAsyncCallback(async () => {
    const buildFiles = await loadBuildFiles.execute();

    if (buildFiles.client.length + buildFiles.server.length === 0) {
      if (model.config.projectType === 'Site') {
        throw new CliError({
          code: CliErrorCode.BuildOutputMissing({
            reason: "Couldn't find any client or server build output files.",
          }),
          cause: null,
        });
      }

      // No client or server output was built, so there is nothing to deploy
      // and the manifest is published on its own.
      return DeploymentTarget.App({});
    }

    const { deploymentBaseUrl, deploymentId } =
      await deployFiles.execute(buildFiles);

    return DeploymentTarget[model.config.projectType]({
      deploymentUrl: deploymentBaseUrl,
      deploymentId,
    });
  });

  const createPreviewIdAction = useAsyncCallback(
    async (_, serverUrl?: string, deploymentId?: string) => {
      const gitCommitHash = (await isInsideGitRepo(model.projectFolder))
        ? await getGitLatestCommitHash(model.projectFolder)
        : undefined;

      const { appManifest: rawManifest, componentPlaceholderFieldMasks } =
        await processAppManifest({
          projectFolder: model.projectFolder,
          config: model.config,
          serverUrl,
        });

      const appManifest =
        deploymentId && serverUrl
          ? updateManifestWithBackendWorker(
              rawManifest,
              deploymentId,
              serverUrl,
              label,
              gitCommitHash
            )
          : rawManifest;

      let previewId: string;
      if (existingPreviewId) {
        previewId = await devCenterOverrides.updateOverrideWithNoSideEffects({
          id: existingPreviewId,
          appId: model.config.appId,
          appManifest,
          componentFieldMasks: componentPlaceholderFieldMasks,
          projectId: model.releaseAppId,
        });
      } else {
        previewId = await devCenterOverrides.createComponentsOverride({
          appId: model.config.appId,
          appManifest,
          projectId: model.releaseAppId,
          experiments: toComponentExperiments(appManifest.components),
        });
      }

      return { previewId, appManifest };
    }
  );

  const { status } = useAsync(async () => {
    await assertBuildOutputExists(model.projectFolder, model.config);

    const deployment = baseUrl
      ? DeploymentTarget[model.config.projectType]({ deploymentUrl: baseUrl })
      : await uploadApplicationAction.execute();

    const { deploymentUrl, deploymentId } = deployment;

    const { previewId, appManifest } = await createPreviewIdAction.execute(
      deploymentUrl,
      deploymentId
    );

    const result: PreviewResult = { deployment, previewId, appManifest };
    onPreviewCreated?.(result);

    return result;
  }, []);

  return {
    uploadStatus: uploadApplicationAction.status,
    createPreviewStatus: createPreviewIdAction.status,
    status,
  };
}
